code='''def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); groups={}
    for r in range(h):
      for c in range(w):
        col=grid[r][c]
        if col and (r,c) not in seen:
          st=[(r,c)]; seen.add((r,c)); cells=[]
          while st:
            y,x=st.pop(); cells.append((y,x))
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
              q=(y+dy,x+dx)
              if 0<=q[0]<h and 0<=q[1]<w and q not in seen and grid[q[0]][q[1]]==col:
                seen.add(q); st.append(q)
          groups.setdefault(col,[]).append(cells)
    out=[[0]*w for _ in range(h)]
    for col,cs in groups.items():
      side=0 if col==min(groups) else 5
      cs.sort(key=len)
      for i,cells in enumerate(cs):
        minr=min(y for y,x in cells); minc=min(x for y,x in cells)
        targetr=4 if i==0 else 7
        targetc=side
        for y,x in cells:
          yy=targetr+y-minr; xx=targetc+x-minc
          if yy<h and xx<w: out[yy][xx]=col
    return out
'''
